import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    if n == 1:
        if a[0] == 0:
            print("YES")
            print("0")
        else:
            print("NO")
        return

    count_zeros = a.count(0)

    if count_zeros == 0:
        print("NO")
        return

    if count_zeros == 1:
        idx = a.index(0)
        if idx == n - 1:
            print("YES")
            res = []
            for i in range(n):
                if i > 0:
                    res.append("->")
                if i == idx:
                    if i == n - 1:
                        res.append(str(a[i]))
                    else:
                        res.append("(")
                        res.append(str(a[i]))
                        res.append("->")
                        res.append(str(a[i+1]))
                        res.append(")")
                        i += 1
                elif i < idx:
                    if i == idx - 1:
                        res.append("(")
                        res.append(str(a[i]))

                    else:
                        res.append(str(a[i]))
                else:
                    pass

            # Rebuild properly
            parts = []
            for i in range(n):
                parts.append(str(a[i]))

            expr_parts = []
            for i in range(n):
                if i > idx:
                    break
                if i == idx:
                    if i == n - 2:
                        expr_parts.append(f"({parts[i]}->{parts[i+1]})")
                        i += 1
                    else:
                        expr_parts.append(parts[i])
                else:
                    expr_parts.append(parts[i])

            final_expr = "->".join(expr_parts)
            if len(expr_parts) < n - 1:
                for i in range(len(expr_parts), n):
                    if i == n - 1:
                        final_expr += f"->{parts[i]}"
                    else:
                        final_expr += f"->({parts[i]}->{parts[i+1]})"

            print(final_expr)
        else:
            print("YES")
            res = []
            for k in range(idx):
                res.append(str(a[k]))
            res.append("->")
            res.append("(")
            res.append(str(a[idx]))
            res.append("->")
            for k in range(idx + 1, n):
                if k > idx + 1:
                    res.append("->")
                res.append(str(a[k]))
            res.append(")")
            print("".join(res))
    else:
        print("YES")
        res = []
        for i in range(n):
            if i > 0:
                res.append("->")
            res.append(str(a[i]))
        print("".join(res))

solve()
